2074af9d3a1398a52e5799a5a2e9976d65242fcfaac0c4dd76d3e870672daf","catalog_sha256":"1d020c267273134a377991204f38543034a5d40e4aa2e7d492c8922e43c03c13","capability_keys":["narrative.scene","combat.encounter","d100.native","terminal.result"],"catalog_version":"mission-factory-catalog/1.4","allowed_auth_ids":["f0856d53-83a6-4de0-bc0c-12c87916e665","b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b"],"authority_sha256":"d83245256ef07baf35660388218974c32350374be903c6c7a8ea50f9f8724630"},"previous_kind":{"enabled":true,"bound_at":"2026-10-14T18:35:43.6768+00:00","singleton":true,"expires_at":"2026-10-14T20:35:43.6768+00:00","request_key":"4da1143a-8d60-465c-85de-09796fc2217c","review_sha256":"ef8ff1449fee8e6fb62f9b8a38fa795f31948386124b85cca4134e5daaafef04","source_sha256":"a72074af9d3a1398a52e5799a5a2e9976d65242fcfaac0c4dd76d3e870672daf","catalog_sha256":"1d020c267273134a377991204f38543034a5d40e4aa2e7d492c8922e43c03c13","capability_keys":["narrative.scene","combat.encounter","d100.native","terminal.result"],"catalog_version":"mission-factory-catalog/1.4","allowed_auth_ids":["f0856d53-83a6-4de0-bc0c-12c87916e665","b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b"],"authority_sha256":"d83245256ef07baf35660388218974c32350374be903c6c7a8ea50f9f8724630"},"effective_from":"2026-10-14T22:04:19.535339+00:00","source_row_sha256":"4b566d5a60bb24d684fe81c21007c98e767b560438affd2b8d76ab512dd933da","root_authority_sha256":"838df6aff3cf71b72426a8056f5cddae8a8cf12c12b371e577617ce9cf96e6d1","original_certificate_sha256":"181e191bd352722e55691f99ff7e012e314659955c6dc9f959e40ec4074d29ba"},"participant_check":"CHECK ((engagement_state = ANY (ARRAY['attivo'::text, 'sospeso'::text, 'concluso'::text])))","participant_index":"CREATE UNIQUE INDEX master_v2_participants_impegno_idx ON public.master_v2_participants USING btree (character_id) WHERE ((engagement_state = ANY (ARRAY['attivo'::text, 'sospeso'::text])) AND (character_id <> '6bceee99-974f-426b-8d92-38b43b4a4267'::uuid))","current_lease_receipt":{"draft_id":"36e2ebe