 t:=preimage::jsonb;S:=encode(extensions.digest(convert_to(preimage,'UTF8'),'sha256'),'hex');
 B:=mission_factory_owner.sha(jsonb_build_object('schema_version','human-release-identity-key/1','human_release_sha256',S));
 IF preimage IS NULL OR S IS NULL OR S='37dac90525b249f53fc0404b50adb4ed92df0123649326c99260bf656119d806'
 OR NOT mission_factory_owner.keys_exact_v2(t,ARRAY['schema_version','db_core','client','edge','config','legacy_dependency'])
 OR t->>'schema_version' IS DISTINCT FROM 'human-ordinary-release-tuple/1'
 OR e#>>'{owner_payload,revision_sha256}' IS DISTINCT FROM S
 OR e#>'{owner_payload,canonical_tuple}' IS DISTINCT FROM t
 OR e#>>'{owner_payload,independent_review_ref}' IS DISTINCT FROM e->>'review_ref'
 OR e#>>'{owner_payload,cross_version_assessment,reviewed_delta_manifest_sha256}' IS DISTINCT FROM e->>'source_sha256'
 OR e#>>'{owner_payload,cross_version_assessment,published_assets_manifest_sha256}' IS DISTINCT FROM '8695a36fa90cf51c103af605cdcab01860648ae9309d4cc9c7c3b31018428f7d'
 OR e#>>'{owner_payload,schema_version}' IS DISTINCT FROM 'human-owner-accepted-release/1'
 THEN RAISE EXCEPTION 'OWNER_ACCEPTANCE_CURRENT_TUPLE_REQUIRED';END IF;
 SELECT * INTO STRICT v_owner_fixed30_before FROM mission_factory_owner.quest_fixed30_admission WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT policy FROM mission_factory_owner.quest_reward_policy_versions WHERE id=(e#>>'{identity,policy_id}')::uuid FOR SHARE;
 IF policy.id NOT IN('2fe96b8c-37f6-4910-a38e-2ddd47f5a12a'::uuid,'16914fa7-a195-4140-b96d-3b26088fcfcf'::uuid)
 OR policy.scope IS DISTINCT FROM 'staff' OR NOT policy.qualified
 OR policy.document_sha256 IS DISTINCT FROM '34197acc065af70dc89ac15d54c19044f4e5af07c91b5869eb0b360a0fcfef19'
 OR policy.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(policy.document)
 OR policy.document IS DISTINCT FROM mission_factory_owner.quest_reward_fixed30_document_v2()
 OR v_owner_fixed30_before.public_enabled OR v_owner_fixed30_before.staff_enabled OR v_owner_fixed30_before.public_staff_enabled OR v_owner_fixed30_before.scheduler_staff_enabled OR v_owner_fixed30_before.scheduler_public_enabled
 OR v_owner_fixed30_before.allowed_auth_ids IS DISTINCT FROM '{}'::uuid[]
 OR EXISTS(SELECT 1 FROM mission_public_owner.release_admissions_v1)
 OR EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1)
 THEN RAISE EXCEPTION 'OWNER_ACCEPTANCE_POLICY_OR_ABSENCE_CAS';END IF;
 INSERT INTO mission_public_owner.release_admissions_v1(release_sha256,db_sha256,edge_sha256,client_sha256,configuration_sha256,contract_version,independent_review_ref,staff_evidence_ref,qualified_at,public_enabled)
 VALUES(S,t#>>'{db_core,sha256}',t#>>'{edge,sha256}',t#>>'{client,sha256}',t#>>'{config,sha256}','mission-public-admission/1',e->>'review_ref','AUTHORIZED_TEST_MANIFEST:'||(e->>'manifest_ref'),statement_timestamp(),false),
 (B,t#>>'{db_core,sha256}',t#>>'{edge,sha256}',t#>>'{client,sha256}',t#>>'{config,sha256}','mission-public-admission/1',e->>'review_ref','HUMAN_IDENTITY_SOURCE_ONLY:'||S,statement_timestamp(),false);
 identity_payload:=jsonb_build_object('schema_version','human-ordinary-release-identity/1','revision_sha256',B,'human_release_sha256',S,'canonical_preimage',preimage,'canonical_tuple',t,'source_review_ref',e->>'review_ref','review_findings','{"P0":0,"P1":0,"P2":0}'::jsonb,'actual_client_binding_sha256',t#>>'{client,sha256}','actual_edge_binding_sha256',t#>>'{edge,sha256}','provider_calls',0,'staff_guards_verified',true,'published_assets_verified',true,'observed_revision_sha256',S);
 INSERT INTO mission_public_owner.public_qualification_attestations_v1(release_sha256,request_key,payload,payload_sha256,positive_staff_evidence_ref,authorized_test_manifest_ref,created_by)
 VALUES(B,(e#>>'{identity,request_key}')::uuid,identity_payload,mission_factory_owner.sha(identity_payload),'SOURCE_REVIEW_ONLY:'||(e->>'review_ref'),e->>'manifest_ref','postgres');
 verified:=mission_public_owner.human_positive_qualification_attest_v1(S,(e->>'request_key')::uuid,e->>'manifest_ref',e->>'positive_ref',e->'owner_payload');
 IF verified IS NULL OR verified->>'schema_version' IS DISTINCT FROM 'human-owner-accepted-release/1' THEN RAISE EXCEPTION 'OWNER_ACCEPTANCE_ATTESTATION_NOT_VERIFIED';END IF;
 UPDATE mission_public_owner.release_admissions_v1 SET public_enabled=true WHERE release_sha256=S;
 UPDATE mission_factory_owner.quest_fixed30_admission SET public_release_sha256=S,public_policy_id=policy.id,public_qualification_sha256=mission_factory_owner.sha(e->'owner_payload') WHERE singleton;
 IF mission_public_owner.human_positive_qualification_v1(S,true) IS NULL
 OR mission_factory_owner.human_ordinary_release_identity_v1(S,true) IS NULL
 OR (SELECT to_jsonb(x) FROM mission_factory_owner.quest_fixed30_admission x WHERE singleton) IS DISTINCT FROM
 (to_jsonb(v_owner_fixed30_before)||jsonb_build_object('public_release_sha256',S,'public_policy_id',policy.id,'public_qualification_sha256',mission_factory_owner.sha(e->'owner_payload')))
 OR (SELECT count(*) FROM mission_public_owner.release_admissions_v1)<>2
 OR (SELECT count(*) FROM mission_public_owner.public_qualification_attestations_v1)<>2
